STACK_OVERRIDES = {
    'magnum': 'HTML · CSS · JavaScript (интерактивная версия для портфолио)',
    'photo-animation': 'HTML · CSS · JavaScript',
    'tatiana': 'React · TypeScript · Vite',
    'ppbot': 'HTML Canvas · JavaScript · Telegram WebApp SDK · JSON',
    'gigant': 'Python · FastAPI · AgentLoopService',
    'desert-wheels': 'React · TypeScript · Vite · jsPDF',
    'women-strange': 'HTML · CSS · JavaScript',
    'linux-lab': 'Linux · GnuPG · KGpg · iptables · pfSense · Steghide · ClamAV',
    'trekpodarok': 'React · TypeScript · Vite',
    'portfolio-archive': 'React · TypeScript · Vite · Tailwind · GSAP · Three.js',
    'stepbystep': 'React · TypeScript · React Router · Vite · Tailwind',
    'skazka': 'React · TypeScript · Vite · Tailwind',
    'twitter-automation': 'Python · CLI · Windows Scheduler',
    'topgadalkin': 'Next.js · React · TypeScript · Tailwind · Vercel KV',
}

def meta_description(record):
    # Build a distinct search snippet from the outcome, avoiding generic boilerplate.
    outcome = record['result'].replace('По словам автора, ', '')
    value = f"{record['shortTitle']}: {outcome}"
    if len(value) > 164:
        value = value[:161].rsplit(' ', 1)[0].rstrip('.,;:') + '…'
    return value

def escape(value):
    return html.escape(str(value), quote=True)

def main():
    path = ROOT/'portfolio/data.json'
    projects = json.loads(path.read_text(encoding='utf-8'))
    ids = [p['id'] for p in projects]
    if len(ids) != 35 or set(ids) != set(entries):
        raise ValueError(f'Catalog mismatch: {set(ids)^set(entries)}; count {len(ids)}')
    for p in projects:
        c = entries[p['id']]
        p.update({k:v for k,v in c.items() if k!='id'})
        if p['id'] in STACK_OVERRIDES:
            p['stack'] = STACK_OVERRIDES[p['id']]
        if p['id'] == 'support-rag':
            p['flow'] = 'Аккаунт поддержки или webchat → синхронизация → Telegram-топик → FAQ/RAG-черновик → Edit/Regen/Send → ответ от аккаунта поддержки.'
            p['boundary'] = 'Отправка от аккаунта поддержки подтверждена автором как часть исходного продукта. Сквозной live-run с аккаунтом сейчас не переснят; Telegram-экран обезличен, webchat и AI replay проверены отдельно.'
        p['seoDescription'] = meta_description(c)
        p['subtitle'] = c['shortDescription']
        p['intro'] = c['caseIntro']
    path.write_text(json.dumps(projects, ensure_ascii=False, indent=2)+'\n', encoding='utf-8')
    matrix = ['# Content matrix','', 'Canonical catalog: 35 projects. Runtime source: `portfolio/data.json`. Copy is grounded in `projects/<id>/case.md`; proof and limits remain explicit.','']
    for p in projects:
        matrix += [f"## {p['name']} · `{p['id']}`", '',
          f"- **Category:** {p['category']}", f"- **SEO title:** {p['seoTitle']}", f"- **SEO description:** {p['seoDescription']}",
          f"- **Short card title:** {p['shortTitle']}", f"- **Short description:** {p['shortDescription']}",
          f"- **Problem:** {p['problem']}", f"- **What I built:** {p['built']}", f"- **Result:** {p['result']}",
          f"- **Proof:** {p['proof']}", f"- **Stack:** {p['stack'] if p['stack'] != 'Подробности в исследовании' else 'Не установлен по доступным материалам'}",
          f"- **Keywords:** {', '.join(p['keywords'])}", f"- **Case intro:** {p['caseIntro']}", '']
    (ROOT/'CONTENT_MATRIX.md').write_text('\n'.join(matrix).rstrip()+'\n', encoding='utf-8')

    legacy_path = ROOT/'site/case.html'
    template = legacy_path.read_text(encoding='utf-8').replace('<meta name="robots" content="noindex,follow">','').replace('editorial.css?v=20260922-d','editorial.css?v=20260923-copy-v1').replace('app.js?v=20260923-roulette-v3','app.js?v=20260923-copy-v1')
    legacy = template.replace('<title>Кейс — Никита Солонуха</title>', '<meta name="robots" content="noindex,follow"><title>Кейс — Никита Солонуха</title>')
    legacy_path.write_text(legacy, encoding='utf-8')
    for p in projects:
        title = p['seoTitle'] + ' | Никита Солонуха'
        canonical = f"{BASE}/site/case-{quote(p['id'])}.html"
        image = f"{BASE}/portfolio/{p['desktop'].removeprefix('../portfolio/')}" if not p['desktop'].startswith('../') else f"{BASE}/{p['desktop'][3:]}"
        if p['id'] in ('roulette','photo-animation','ep-beauty','trekpodarok','skazka','topgadalkin'):
            # Their original visual-first case pages stay the public route; reviewed separately.
            continue
        content = template.replace('<title>Кейс — Никита Солонуха</title>', f'<title>{escape(title)}</title>')
        content = content.replace('Проект Никиты Солонухи: настоящий интерфейс, сценарий и результат.', escape(p['seoDescription']))
        tags = f'<link rel="canonical" href="{escape(canonical)}"><meta property="og:type" content="article"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(p["seoDescription"])}"><meta property="og:url" content="{escape(canonical)}"><meta property="og:image" content="{escape(image)}"><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{escape(title)}"><meta name="twitter:description" content="{escape(p["seoDescription"])}"><meta name="twitter:image" content="{escape(image)}">'
        content = content.replace('</head>', tags+'</head>', 1)
        fallback = f'<div class="case-fallback shell"><h1>{escape(p["name"])}</h1><p>{escape(p["caseIntro"])}</p><h2>Задача</h2><p>{escape(p["problem"])}</p><h2>Что я сделал</h2><p>{escape(p["built"])}</p><h2>Результат</h2><p>{escape(p["result"])}</p></div>'
        content = content.replace('<div id="case-root"></div>', f'<div id="case-root">{fallback}</div>')
        (ROOT/f'site/case-{p["id"]}.html').write_text(content, encoding='utf-8')

    public_paths = ['/site/', '/site/about.html','/site/work.html','/site/archive.html','/site/contact.html']
    public_paths += [f'/review/{p["id"]}.html' if p['id'] in ('roulette','photo-animation','ep-beauty','trekpodarok','skazka','topgadalkin') else f'/site/case-{p["id"]}.html' for p in projects]
    sitemap = '<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + ''.join(f'  <url><loc>{escape(BASE+x)}</loc></url>\n' for x in public_paths) + '</urlset>\n'
    (ROOT/'sitemap.xml').write_text(sitemap, encoding='utf-8')
    (ROOT/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {BASE}/sitemap.xml\n', encoding='utf-8')
    print(f'Built {len(projects)} content records, 29 static case pages, sitemap and robots.')

if __name__ == '__main__':
    main()
